/* Actual two-player command flow, finite PP, next-wave reset and legal save. */
#define main retained_doubles_main
#include "doubles_host_test.c"
#undef main
int main(void){setup(1);CHECK(r.double_battle);r.n_items=0;gc_items_to_battle(&r);
 for(int k=0;k<2;k++){gc_starter starter={.species=k?SPECIES_ID_ORANGURU:SPECIES_ID_MAUSHOLD,.tera_type=-1};memset(starter.ivs,15,6);gc_mon_new_player(&r,&r.party[k],&starter,100);pr_pokemon*p=&r.party[k].b;p->on_field=true;p->hp=p->stats[STAT_HP]=100000;p->stats[STAT_ATK]=100;p->stats[STAT_SPD]=k?500:1000;p->n_moves=k?1:2;p->moves[0]=k?MOVE_ID_INSTRUCT:MOVE_ID_POPULATION_BOMB;if(!k)p->moves[1]=MOVE_ID_DAZZLING_GLEAM;p->stat_stages[STAT_ACC-1]=6;p->ability=p->custom_ability=p->base_ability=ABILITY_ID_NONE;p->ability_override=-1;p->passive_flag=false;r.bt.field[k]=r.bt.party[0][k]=p;}
 for(int k=2;k<4;k++){pr_pokemon*p=r.bt.field[k];CHECK(p);p->hp=p->stats[STAT_HP]=1;p->stats[STAT_SPD]=10;p->n_moves=1;p->moves[0]=MOVE_ID_SPLASH;p->pp_used[0]=0;p->pp_up[0]=0;p->max_pp_override[0]=-1;p->custom_ability=p->ability=p->base_ability=ABILITY_ID_NONE;p->ability_override=-1;p->passive_flag=false;}
 choose(&r,(gc_choice){GC_CH_FIGHT,0,-1,0});CHECK(r.screen.kind==GC_SCREEN_TARGET&&r.screen.target_ok[1]);choose(&r,(gc_choice){GC_CH_TARGET,1,0,0});CHECK(r.screen.kind==GC_SCREEN_COMMAND&&r.screen.slot==1);choose(&r,(gc_choice){GC_CH_FIGHT,0,-1,0});CHECK(r.screen.kind==GC_SCREEN_TARGET&&r.screen.target_ok[0]);choose(&r,(gc_choice){GC_CH_TARGET,0,0,0});
 CHECK(!r.eng.overflow&&!r.battle_events_overflow&&!r.bt.n_unported);CHECK(r.screen.kind==GC_SCREEN_COMMAND&&r.screen.slot==0);CHECK(r.party[0].b.pp_used[0]==2&&r.party[1].b.pp_used[0]==1);int hits=0,damage=0;for(int i=0;i<r.n_battle_events;i++)if(r.battle_events[i].type==PR_EV_DAMAGE&&r.battle_events[i].battler==1){hits++;damage+=r.battle_events[i].value;}CHECK(hits==20&&r.party[1].b.hp==100000-damage);CHECK(!r.party[1].b.n_attacks_received&&!pr_received_oldest_positive(&r.bt,&r.party[1].b)&&!pr_received_damage_from(&r.bt,&r.party[1].b,r.party[0].b.id));CHECK(!r.bt.n_unported);CHECK(!gc_run_can_save(&r)&&!gc_run_save(&r,save,sizeof save));
 int wave=r.wave;for(int step=0;step<80&&r.wave==wave;step++){gc_choice c={0};switch(r.screen.kind){case GC_SCREEN_COMMAND:c=(gc_choice){GC_CH_FIGHT,r.screen.slot==0?1:0,-1,0};break;case GC_SCREEN_TARGET:c=(gc_choice){GC_CH_TARGET,0,0,0};break;case GC_SCREEN_REWARD:c.kind=GC_CH_SKIP;break;case GC_SCREEN_LEARN_MOVE:c=(gc_choice){GC_CH_FORGET,-1,0,0};break;case GC_SCREEN_EVOLVE:c.kind=GC_CH_CANCEL;break;case GC_SCREEN_CHECK_SWITCH:c.kind=GC_CH_CONFIRM;break;default:fprintf(stderr,"received lifecycle screen%d\n",r.screen.kind);CHECK(false);}choose(&r,c);}
 for(int step=0;step<20&&r.screen.kind==GC_SCREEN_CHECK_SWITCH;step++){choose(&r,(gc_choice){GC_CH_CONFIRM,0,0,0});}
 CHECK(r.wave==wave+1&&gc_run_can_save(&r));CHECK(!r.party[1].b.n_attacks_received&&!pr_received_oldest_positive(&r.bt,&r.party[1].b)&&!pr_received_damage_from(&r.bt,&r.party[1].b,r.party[0].b.id));CHECK(!r.bt.n_unported);size_t n=gc_run_save(&r,save,sizeof save);const char*why=NULL;CHECK(n&&gc_run_load(&back,save,n,&why)&&!back.load_dropped);CHECK(!back.party[1].b.n_attacks_received&&!pr_received_oldest_positive(&back.bt,&back.party[1].b)&&!pr_received_damage_from(&back.bt,&back.party[1].b,back.party[0].b.id)&&!back.bt.n_unported);CHECK(back.party[0].b.pp_used[0]==2);
 printf("Received history: actual doubles commands, twenty hits, next encounter and save; %d checks passed\n",checks);return 0;}
